import React from "react";
import { Link } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";

export default function Login() {
  return (
    <div
      className="min-vh-100 d-flex align-items-center justify-content-center"
      style={{
        background: "linear-gradient(135deg, #fdf6ec, #f7efe5)",
      }}
    >
      <div className="container">
        <div className="row justify-content-center">
          <div className="col-md-6 col-lg-4">
            <div className="card border-0 shadow-lg rounded-4 p-4">
              <div className="text-center mb-4">
                <h3 className="fw-bold text-brown">Welcome Back 🌰</h3>
                <p className="text-muted mb-0">
                  Login to continue shopping premium dry fruits
                </p>
              </div>

              <form>
                <div className="mb-3">
                  <label className="form-label fw-semibold">
                    Email Address
                  </label>
                  <input
                    type="email"
                    className="form-control rounded-3"
                    placeholder="you@email.com"
                  />
                </div>

                <div className="mb-3">
                  <label className="form-label fw-semibold">
                    Password
                  </label>
                  <input
                    type="password"
                    className="form-control rounded-3"
                    placeholder="••••••••"
                  />
                </div>

                <div className="d-flex justify-content-between align-items-center mb-4">
                  <div className="form-check">
                    <input
                      className="form-check-input"
                      type="checkbox"
                      id="rememberMe"
                    />
                    <label
                      className="form-check-label small"
                      htmlFor="rememberMe"
                    >
                      Remember me
                    </label>
                  </div>

                  <Link
                    to="/forgot-password"
                    className="small text-decoration-none text-brown"
                  >
                    Forgot password?
                  </Link>
                </div>

                <button
                  type="submit"
                  className="btn w-100 py-2 fw-semibold rounded-3"
                  style={{
                    backgroundColor: "#8b5e3c",
                    color: "#fff",
                  }}
                >
                  Login
                </button>

                <p className="text-center mt-4 mb-0">
                  Don’t have an account?{" "}
                  <Link
                    to="/register"
                    className="text-brown fw-semibold text-decoration-none"
                  >
                    Register
                  </Link>
                </p>
              </form>
            </div>
          </div>
        </div>
      </div>

      {/* Theme Styles */}
      <style>
        {`
          .text-brown {
            color: #8b5e3c;
          }

          .form-control:focus {
            border-color: #8b5e3c;
            box-shadow: 0 0 0 0.2rem rgba(139, 94, 60, 0.25);
          }

          .card {
            animation: fadeInUp 0.6s ease;
          }

          @keyframes fadeInUp {
            from {
              opacity: 0;
              transform: translateY(20px);
            }
            to {
              opacity: 1;
              transform: translateY(0);
            }
          }
        `}
      </style>
    </div>
  );
}
